use super::{archives,model::*,reconcile::{self,Policy},recovery,store};
use crate::private_registry::{self,Document};
use std::{path::PathBuf,os::unix::fs::PermissionsExt,cell::Cell};
#[allow(dead_code)]#[path="fixtures/reader_v2.rs"]mod reader_v2;
struct Files(PathBuf);
impl Files{fn new()->Self{let p=std::env::temp_dir().join(format!("coucou-reconcile-{}",crate::assistant_memory::new_id()));std::fs::create_dir(&p).unwrap();std::fs::set_permissions(&p,std::fs::Permissions::from_mode(0o700)).unwrap();Self(p)}fn path(&self)->PathBuf{self.0.join("session-drafts.json")}}
impl Drop for Files{fn drop(&mut self){let _=std::fs::remove_dir_all(&self.0);}}
fn utf(s:&str)->Vec<u16>{s.encode_utf16().collect()}
fn target(id:&str)->Target{Target{pet_id:utf("agent_codex"),provider:utf("codex"),origin:Origin::Mochi,session_id:utf(id),conversation_id:Some(utf(id))}}
fn batch()->Import{Import{schema_version:1,source_id:"12345678-1234-1234-1234-123456789abc".into(),revision:"11".into(),records:vec![Record{target:target("A"),revision:"10".into(),text_units:vec![0xd800,0,0xdfff,60,62]},Record{target:target("B"),revision:"11".into(),text_units:utf("original B")} ]}}
fn seed(f:&Files){store::write(&f.path(),target("A"),None,utf("native winner"),||Ok(())).unwrap();}
fn review(f:&Files,b:&Import,policy:Policy)->reconcile::Review{reconcile::review(&f.path(),b,policy,None,None,0,100,||Ok(())).unwrap().review}
fn commit(f:&Files,b:&Import,policy:Policy)->ImportReceipt{reconcile::commit(&f.path(),b,review(f,b,policy),true,||101,||Ok(())).unwrap()}
fn raw_archive(f:&Files,reference:&Retained)->PathBuf{f.0.join(format!("draft-source-{}-{}.json",reference.receipt.source_id,reference.receipt.fingerprint))}
#[test]fn retain_only_preserves_entire_divergent_original_without_replacing_native_or_creating_conversations(){
 let f=Files::new();seed(&f);let b=batch();let before=std::fs::read(f.path()).unwrap();assert_eq!(store::import(&f.path(),b.clone(),||Ok(())).err(),Some("draftImportConflict"));let page=reconcile::review(&f.path(),&b,Policy::RetainOnly,None,None,0,100,||Ok(())).unwrap();assert_eq!(page.review.summary.total,2);assert_eq!(page.review.summary.conflicts,1);assert_eq!(page.review.summary.missing,1);assert!(page.review.summary.can_merge);assert_eq!(page.rows[0].native.as_ref().unwrap().text_units,utf("native winner"));assert_eq!(std::fs::read(f.path()).unwrap(),before);
 let receipt=reconcile::commit(&f.path(),&b,page.review,true,||101,||Ok(())).unwrap();let current=private_registry::load_at::<Registry>(&f.path()).unwrap();assert_eq!(current.registry.schema_version,3);assert_eq!(current.registry.records.len(),1);assert_eq!(current.registry.records[0].text_units,utf("native winner"));let sources=archives::list(&f.path(),||Ok(())).unwrap();assert_eq!(sources.len(),1);assert_eq!(sources[0].status,"retained");assert_eq!(sources[0].records,2);assert_eq!(sources[0].reference.receipt,receipt);let original=archives::read(&f.path(),&sources[0].reference).unwrap();assert_eq!(original.registry.source.as_ref().unwrap(),&b);assert!(!f.0.join("conversations.json").exists());assert_eq!(std::fs::metadata(raw_archive(&f,&sources[0].reference)).unwrap().permissions().mode()&0o777,0o600);
}
#[test]fn merge_adds_only_absent_destinations_then_lost_ack_never_reimports_over_native_edits(){
 let f=Files::new();seed(&f);let b=batch();let receipt=commit(&f,&b,Policy::MergeCompatible);assert_eq!(store::read(&f.path(),target("A"),||Ok(())).unwrap().unwrap().text_units,utf("native winner"));assert_eq!(store::read(&f.path(),target("B"),||Ok(())).unwrap(),Some(b.records[1].clone()));
 store::write(&f.path(),target("B"),Some("11".into()),utf("later native B"),||Ok(())).unwrap();let bytes=std::fs::read(f.path()).unwrap();assert_eq!(store::import(&f.path(),b.clone(),||Ok(())).unwrap(),receipt);assert_eq!(std::fs::read(f.path()).unwrap(),bytes);
 let again=review(&f,&b,Policy::RetainOnly);assert!(again.summary.already_retained);assert!(!again.summary.can_merge);reconcile::commit(&f.path(),&b,again,true,||102,||Ok(())).unwrap();assert_eq!(std::fs::read(f.path()).unwrap(),bytes);assert!(reconcile::review(&f.path(),&b,Policy::MergeCompatible,None,None,0,100,||Ok(())).is_err());
}
#[test]fn changed_source_requires_new_review_and_keeps_both_immutable_originals_under_same_source_id(){
 let f=Files::new();seed(&f);let b=batch();let first=commit(&f,&b,Policy::RetainOnly);let mut changed=b.clone();changed.revision="12".into();changed.records[0].revision="12".into();changed.records[0].text_units=utf("newer original");assert_eq!(store::import(&f.path(),changed.clone(),||Ok(())).err(),Some("draftImportChanged"));let second=commit(&f,&changed,Policy::RetainOnly);assert_ne!(first.fingerprint,second.fingerprint);assert_eq!(first.source_id,second.source_id);let originals=archives::list(&f.path(),||Ok(())).unwrap();assert_eq!(originals.len(),2);assert_eq!(store::import(&f.path(),b,||Ok(())).unwrap(),first);assert_eq!(store::import(&f.path(),changed,||Ok(())).unwrap(),second);
}
#[test]fn partial_archive_is_visible_recoverable_and_not_an_accepted_migration_then_fresh_review_reuses_it(){
 let f=Files::new();seed(&f);let b=batch();let before=std::fs::read(f.path()).unwrap();let reviewed=review(&f,&b,Policy::RetainOnly);assert_eq!(reconcile::commit_prepared(&f.path(),&b,reviewed,true,||101,||Ok(()),||Err("injected before primary publication")).err(),Some("injected before primary publication"));assert_eq!(std::fs::read(f.path()).unwrap(),before);let sources=archives::list(&f.path(),||Ok(())).unwrap();assert_eq!(sources[0].status,"pending");let archived=std::fs::read(raw_archive(&f,&sources[0].reference)).unwrap();assert_eq!(store::import(&f.path(),b.clone(),||Ok(())).err(),Some("draftImportConflict"));
 let page=recovery::list_source(&f.path(),recovery::Owner{pet_id:utf("agent_codex"),provider:utf("codex")},0,16,None,Some(&sources[0].reference),||Ok(()),|_|recovery::Availability::Orphan).unwrap();assert_eq!(page.total,2);
 commit(&f,&b,Policy::RetainOnly);assert_eq!(archives::list(&f.path(),||Ok(())).unwrap()[0].status,"retained");assert_eq!(std::fs::read(raw_archive(&f,&sources[0].reference)).unwrap(),archived);
}
#[test]fn changed_native_catalogue_after_archive_refuses_primary_and_keeps_the_new_native_data(){
 let f=Files::new();seed(&f);let b=batch();let reviewed=review(&f,&b,Policy::MergeCompatible);assert_eq!(reconcile::commit_prepared(&f.path(),&b,reviewed,true,||101,||Ok(()),||{store::write(&f.path(),target("C"),None,utf("concurrent C"),||Ok(()))?;Ok(())}).err(),Some("registryConflict"));let current=private_registry::load_at::<Registry>(&f.path()).unwrap();assert_eq!(current.registry.schema_version,2);assert!(current.registry.retained_sources.is_empty());assert_eq!(store::read(&f.path(),target("C"),||Ok(())).unwrap().unwrap().text_units,utf("concurrent C"));assert_eq!(archives::list(&f.path(),||Ok(())).unwrap()[0].status,"pending");
}
#[test]fn revoked_owner_or_expired_review_after_archive_never_claims_acceptance(){
 for failure in ["revoked","expired"]{let f=Files::new();seed(&f);let b=batch();let revoked=Cell::new(false);let time=Cell::new(101);let before=std::fs::read(f.path()).unwrap();let reviewed=review(&f,&b,Policy::RetainOnly);let result=reconcile::commit_prepared(&f.path(),&b,reviewed,true,||time.get(),||if revoked.get(){Err("unavailable")}else{Ok(())},||{if failure=="revoked"{revoked.set(true);}else{time.set(400);}Ok(())});assert!(result.is_err());assert_eq!(std::fs::read(f.path()).unwrap(),before);assert_eq!(archives::list(&f.path(),||Ok(())).unwrap()[0].status,"pending");}
}
#[test]fn forged_body_policy_revisions_receipt_or_expiry_are_refused_before_archiving(){
 for field in ["body","policy","fingerprint","nativeRevision","receipt","summary","expiry","approval"]{let f=Files::new();seed(&f);let mut b=batch();let mut r=review(&f,&b,Policy::RetainOnly);match field{"body"=>b.records[0].text_units.push(42),"policy"=>r.policy=Policy::MergeCompatible,"fingerprint"=>r.fingerprint="0".repeat(64),"nativeRevision"=>r.native_revision="missing".into(),"receipt"=>r.receipt.source_id="23456789-1234-1234-1234-123456789abc".into(),"summary"=>r.summary.conflicts=0,"expiry"=>r.expires_at=500,_=>{}}assert!(reconcile::commit(&f.path(),&b,r,field!="approval",||101,||Ok(())).is_err(),"{field}");assert!(archives::list(&f.path(),||Ok(())).unwrap().is_empty());}
}
#[test]fn missing_or_tampered_committed_original_blocks_ack_and_is_not_overwritten(){
 for missing in [true,false]{let f=Files::new();seed(&f);let b=batch();commit(&f,&b,Policy::RetainOnly);let source=archives::list(&f.path(),||Ok(())).unwrap().remove(0);let p=raw_archive(&f,&source.reference);if missing{std::fs::remove_file(&p).unwrap();}else{std::fs::write(&p,b"malformed retained source").unwrap();}let before=std::fs::read(f.path()).unwrap();assert!(store::import(&f.path(),b.clone(),||Ok(())).is_err());assert!(archives::list(&f.path(),||Ok(())).is_err());assert!(reconcile::review(&f.path(),&b,Policy::RetainOnly,None,None,0,100,||Ok(())).is_err());assert_eq!(std::fs::read(f.path()).unwrap(),before);if !missing{assert_eq!(std::fs::read(p).unwrap(),b"malformed retained source");}}
}
#[test]fn archived_source_copy_is_exact_and_tampering_during_retention_prevents_primary_publication(){
 let f=Files::new();seed(&f);let b=batch();commit(&f,&b,Policy::RetainOnly);let source=archives::list(&f.path(),||Ok(())).unwrap().remove(0);let request=recovery::Request{catalogue_revision:private_registry::load_at::<Registry>(&f.path()).unwrap().revision,source:target("B"),destination:target("new"),source_archive:Some(source.reference.clone())};let reviewed=recovery::review(&f.path(),request.clone(),100,||Ok(()),|_|Ok(())).unwrap();let before=std::fs::read(f.path()).unwrap();let original=std::fs::read(raw_archive(&f,&source.reference)).unwrap();assert!(recovery::copy(&f.path(),reviewed,true,||101,||Ok(()),|_|{std::fs::write(raw_archive(&f,&source.reference),b"changed").unwrap();Ok(())}).is_err());assert_eq!(std::fs::read(f.path()).unwrap(),before);std::fs::write(raw_archive(&f,&source.reference),original).unwrap();let reviewed=recovery::review(&f.path(),request,100,||Ok(()),|_|Ok(())).unwrap();let copied=recovery::copy(&f.path(),reviewed,true,||101,||Ok(()),|_|Ok(())).unwrap();assert_eq!(copied.text_units,b.records[1].text_units);assert_eq!(archives::read(&f.path(),&source.reference).unwrap().registry.source.unwrap(),b);
}
#[test]fn originals_are_capped_including_unaccepted_partial_artifacts(){
 let f=Files::new();seed(&f);for n in 0..8{let mut b=batch();b.source_id=format!("12345678-1234-1234-1234-{n:012x}");archives::retain(&f.path(),&b,||Ok(())).unwrap();}let mut ninth=batch();ninth.source_id="12345678-1234-1234-1234-000000000009".into();assert_eq!(archives::retain(&f.path(),&ninth,||Ok(())).err(),Some("draftLimit"));let all=archives::list(&f.path(),||Ok(())).unwrap();assert_eq!(all.len(),8);assert!(all.iter().all(|s|s.status=="pending"));
}
#[test]fn full_native_catalogue_still_allows_retain_only_but_not_merge_over_capacity(){
 let f=Files::new();let mut native=Registry::empty();native.revision="1024".into();native.records=(0..1024).map(|n|Record{target:target(&format!("native{n}")),revision:(n+1).to_string(),text_units:vec![]}).collect();private_registry::save_checked(&f.path(),"missing",native,|_,_|Ok(())).unwrap();let b=batch();let r=review(&f,&b,Policy::MergeCompatible);assert!(!r.summary.can_merge);assert_eq!(reconcile::commit(&f.path(),&b,r,true,||101,||Ok(())).err(),Some("draftLimit"));assert!(archives::list(&f.path(),||Ok(())).unwrap().is_empty());commit(&f,&b,Policy::RetainOnly);assert_eq!(private_registry::load_at::<Registry>(&f.path()).unwrap().registry.records.len(),1024);
}
#[test]fn v2_is_read_without_mutation_then_v3_and_subsequent_writes_refuse_old_reader_without_destruction(){
 let f=Files::new();seed(&f);let before=std::fs::read(f.path()).unwrap();assert!(private_registry::load_at::<reader_v2::Registry>(&f.path()).is_ok());archives::list(&f.path(),||Ok(())).unwrap();assert_eq!(std::fs::read(f.path()).unwrap(),before);commit(&f,&batch(),Policy::RetainOnly);let v3=std::fs::read(f.path()).unwrap();assert!(private_registry::load_at::<reader_v2::Registry>(&f.path()).is_err());assert_eq!(std::fs::read(f.path()).unwrap(),v3);store::write(&f.path(),target("C"),None,utf("new native after3"),||Ok(())).unwrap();assert_eq!(private_registry::load_at::<Registry>(&f.path()).unwrap().registry.schema_version,3);assert!(private_registry::load_at::<reader_v2::Registry>(&f.path()).is_err());
}
#[test]fn retained_reference_conservatively_pins_original_cid_and_corrupt_source_does_not_delete_history(){
 let f=Files::new();seed(&f);commit(&f,&batch(),Policy::RetainOnly);let library=f.0.join("conversations.json");assert!(super::retains_conversation(&library,"codex","B"));assert!(!super::retains_conversation(&library,"ollama","B"));let source=archives::list(&f.path(),||Ok(())).unwrap().remove(0);std::fs::remove_file(raw_archive(&f,&source.reference)).unwrap();assert!(super::retains_conversation(&library,"ollama","unknown"));
}
#[test]fn review_pages_bind_native_revision_and_original_sorted_hash_and_do_not_create_an_archive(){
 let f=Files::new();seed(&f);let mut b=batch();b.records=(0..20).map(|n|Record{target:target(&format!("id{n:02}")),revision:"11".into(),text_units:utf("old")}).collect();let page=reconcile::review(&f.path(),&b,Policy::RetainOnly,None,None,0,100,||Ok(())).unwrap();assert_eq!(page.rows.len(),16);assert_eq!(page.next_offset,Some(16));b.records.reverse();let next=reconcile::review(&f.path(),&b,Policy::RetainOnly,Some(&page.review.native_revision),Some(page.review.expires_at),16,101,||Ok(())).unwrap();assert_eq!(next.review,page.review);assert_eq!(next.rows.len(),4);assert!(archives::list(&f.path(),||Ok(())).unwrap().is_empty());
}
#[test]fn full_original_utf16_text_and_identifier_limits_fit_the_retained_file_budget(){
 let f=Files::new();let mut b=batch();b.revision="1024".into();b.records=(0..1024).map(|n|{let mut t=Target{pet_id:vec![65535;128],provider:vec![65535;128],origin:Origin::Mochi,session_id:vec![65535;512],conversation_id:Some(vec![65535;512])};t.session_id[511]=(n+1)as u16;Record{target:t,revision:(n+1).to_string(),text_units:if n<32{vec![65535;TEXT]}else{vec![]}}}).collect();let(reference,_)=archives::retain(&f.path(),&b,||Ok(())).unwrap();assert!(std::fs::metadata(raw_archive(&f,&reference)).unwrap().len()<=64*1024*1024);assert_eq!(archives::read(&f.path(),&reference).unwrap().registry.source.unwrap(),b);
}
#[test]fn a_symlink_instead_of_an_original_is_refused_without_following_or_overwriting_it(){
 let f=Files::new();seed(&f);let b=batch();let receipt=ImportReceipt{schema_version:1,source_id:b.source_id.clone(),fingerprint:b.fingerprint().unwrap()};let destination=f.0.join(format!("draft-source-{}-{}.json",receipt.source_id,receipt.fingerprint));let outside=f.0.join("preserved-other-file");std::fs::write(&outside,b"do not follow").unwrap();std::os::unix::fs::symlink(&outside,&destination).unwrap();let before=std::fs::read(f.path()).unwrap();assert!(reconcile::commit(&f.path(),&b,review(&f,&b,Policy::RetainOnly),true,||101,||Ok(())).is_err());assert_eq!(std::fs::read(outside).unwrap(),b"do not follow");assert_eq!(std::fs::read(f.path()).unwrap(),before);
}
